139	/** The claims people on a sheet make: listed, added, edited and moved through their statuses. */
140	@Service
141	public class ClaimService {
142	
143	    /** Shown in place of a due when the grade has no rate. */
144	    private static final String NO_RATE = "n/a";
145	
146	    private final ClaimRepository claims;
147	    private final PersonRepository people;
148	    private final Dues dues;
149	    private final SheetService sheets;
150	    private final Rollups rollups;
151	    private final PeriodService periods;
152	    private final RoleService roles;
153	    private final Audit audit;
154	
155	    public ClaimService(ClaimRepository claims, PersonRepository people, Dues dues, SheetService sheets,
156	            Rollups rollups, PeriodService periods, RoleService roles, Audit audit) {
157	        this.periods = periods;
158	        this.roles = roles;
159	        this.claims = claims;
160	        this.people = people;
161	        this.dues = dues;
162	        this.sheets = sheets;
163	        this.rollups = rollups;
164	        this.audit = audit;
165	    }
166	
167	    /** The sheet's claims, newest first. */
168	    @Transactional(readOnly = true)
169	    public List<Claim> list(String sheetId) {
170	        return claims.findBySheetIdOrderByIdDesc(sheetId);
171	    }
172	
173	    /**
174	     * Add a claim for a person on the sheet; with no date it is dated the sheet's today. Refused when
175	     * it is dated inside a closed period, or when it is a correction that does not name a SETTLED claim
176	     * of the same person (see {@link #refuseUnlessCorrects}).
177	     */
178	    @Transactional
179	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
180	            Integer corrects) {
181	        Rollups.Rollup before = rollups.take(sheetId);
182	        Person person = person(sheetId, personId);
183	        LocalDate dated = date != null ? date : sheets.today(sheetId);
184	        sheets.lock(sheetId);
185	        periods.refuseIfClosed(sheetId, dated);
186	        refuseIfRetired(person, dated);
187	        refuseUnlessCorrects(sheetId, personId, amount, corrects);
188	        Claim claim = claims.saveAndFlush(new Claim(sheetId, personId, money(amount), dated, clean(note), corrects));
189	        audited("CLAIM_ADDED", sheetId, user, person, claim);
190	        rollups.audit(sheetId, user, before);
191	        return claim;
192	    }
193	
194	    /**
195	     * Change a claim's amount, date, note and the number it corrects; with no date it keeps its own. Only a DRAFT claim can be
196	     * edited: an OPEN one is changed by voiding it and adding a new one. Refused when the claim, or the
197	     * date it moves to, is inside a closed period, or when it would be a correction that does not name a
198	     * SETTLED claim of the same person.
199	     */
200	    @Transactional
201	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
202	            Integer corrects) {
203	        Rollups.Rollup before = rollups.take(sheetId);
204	        sheets.lock(sheetId);
205	        Claim claim = claim(sheetId, claimId);
206	        if (claim.getStatus() != ClaimStatus.DRAFT) {
207	            throw new ResponseStatusException(HttpStatus.CONFLICT,
208	                    "A " + claim.getStatus() + " claim cannot be edited; only a DRAFT can.");
209	        }
210	        periods.refuseIfClosed(sheetId, claim.getDate());
211	        if (date != null) {
212	            periods.refuseIfClosed(sheetId, date);
213	            refuseIfRetired(person(sheetId, claim.getPersonId()), date);
214	        }
215	        refuseUnlessCorrects(sheetId, claim.getPersonId(), amount, corrects);
216	        claim.change(money(amount), date != null ? date : claim.getDate(), clean(note), corrects);
217	        Claim saved = claims.saveAndFlush(claim);
218	        audited("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved);
219	        rollups.audit(sheetId, user, before);
220	        return saved;
221	    }
222	
223	    /**
224	     * Move a claim to a new status, recording the event; refused (and nothing written) when the
225	     * claim's current status does not allow the move. Settling fixes the claim's due at the rate
226	     * the person's grade has in force on the claim's date, or at the figure a statement bound it to,
227	     * with the late charge it has then frozen in.
228	     * Opening numbers the claim and records who opened it; a voided claim keeps its number, which
229	     * is never reused. The user who opened a claim
230	     * is refused when settling it. A clerk is refused settling a claim whose due is above the sheet's
231	     * clerk limit (a due of n/a is within any limit); a steward settles any. A claim dated inside a closed period cannot be moved.
232	     */
233	    @Transactional
234	    public Claim move(String sheetId, String user, long claimId, ClaimStatus next) {
235	        // Opening takes the sheet's lock before reading the claim, so concurrent opens on the
236	        // sheet are serialised: each sees the other's committed claim and number.
237	        Integer number = next == ClaimStatus.OPEN ? sheets.nextClaimNumber(sheetId) : null;
238	        Rollups.Rollup before = rollups.take(sheetId);
239	        sheets.lock(sheetId);
240	        Claim claim = claim(sheetId, claimId);
241	        periods.refuseIfClosed(sheetId, claim.getDate());
242	        if (!claim.getStatus().canBecome(next)) {
243	            throw new ResponseStatusException(HttpStatus.CONFLICT,
244	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
245	        }
246	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
247	            throw new ResponseStatusException(HttpStatus.CONFLICT,
248	                    "The user who opened a claim cannot settle it.");
249	        }
250	        Person person = person(sheetId, claim.getPersonId());
251	        BigDecimal settledDue = next == ClaimStatus.SETTLED
252	                ? dues.settling(claim, person.gradeOn(claim.getDate()))
253	                : null;
254	        if (next == ClaimStatus.SETTLED) {
255	            refuseIfOverClerkLimit(sheetId, user, settledDue);
256	        }
257	        claim.become(next);
258	        if (next == ClaimStatus.OPEN) {
259	            claim.number(number);
260	            claim.openedBy(user);
261	        }
262	        if (next == ClaimStatus.SETTLED) {
263	            claim.settleDue(settledDue);
264	        }
265	        Claim saved = claims.saveAndFlush(claim);
266	        String event = switch (next) {
267	            case OPEN -> "CLAIM_OPENED";
268	            case SETTLED -> "CLAIM_SETTLED";
269	            case VOID -> "CLAIM_VOIDED";
270	            case DRAFT -> throw new IllegalStateException();
271	        };
272	        String suffix = next == ClaimStatus.SETTLED
273	                ? " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
274	                : "";
275	        audited(event, sheetId, user, person, saved, saved.getNumber(), suffix);
276	        rollups.audit(sheetId, user, before);
277	        return saved;
278	    }
279	
280	    /** Refuse a clerk settling a claim whose due is above the sheet's clerk limit. */
281	    private void refuseIfOverClerkLimit(String sheetId, String user, BigDecimal due) {
282	        BigDecimal limit = sheets.clerkLimit(sheetId);
283	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
284	            return;
285	        }
286	        if (Role.CLERK.equals(roles.roleOf(sheetId, user))) {
287	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
288	                    "A clerk cannot settle a claim whose due is above the clerk limit of " + limit.toPlainString() + ".");
289	        }
290	    }
291	
292	    /**
293	     * Refuse a correction (an amount below 0.00) unless it names, by number, a SETTLED claim of the
294	     * same person; and refuse naming a claim to correct on any other claim.
295	     */
296	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, Integer corrects) {
297	        if (amount.signum() >= 0) {
298	            if (corrects != null) {
299	                throw new ResponseStatusException(HttpStatus.CONFLICT,
300	                        "Only a correction, with an amount below 0.00, names a claim it corrects.");
301	            }
302	            return;
303	        }
304	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
305	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
306	                .isPresent();
307	        if (!settled) {
308	            throw new ResponseStatusException(HttpStatus.CONFLICT,
309	                    "A correction must name the number of a SETTLED claim of the same person.");
310	        }
311	    }
312	
313	    /** Refuse a claim dated after its person's retirement. */
314	    private static void refuseIfRetired(Person person, LocalDate date) {
315	        if (!person.canClaimOn(date)) {
316	            throw new ResponseStatusException(HttpStatus.CONFLICT,
317	                    person.getName() + " is retired from " + person.getRetiredFrom() + ": a claim cannot be dated after it.");
318	        }
319	    }
320	
321	    private Claim claim(String sheetId, long claimId) {
322	        return claims.findByIdAndSheetId(claimId, sheetId)
323	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
324	    }
325	
326	    private Person person(String sheetId, long personId) {
327	        return people.findByIdAndSheetId(personId, sheetId)
328	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
329	    }
330	
331	    /** Record the change to the claim once it is committed; a claim with a number carries it. */
332	    private void audited(String event, String sheetId, String user, Person person, Claim claim) {
333	        audited(event, sheetId, user, person, claim, claim.getNumber(), "");
334	    }
335	
336	    private void audited(String event, String sheetId, String user, Person person, Claim claim, Integer number,
337	            String suffix) {
338	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
339	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
340	                + (number != null ? " number=" + number : "") + suffix);
341	    }
342	
343	    /** The due figure a claim shows, without its late charge (see {@link Dues#figure}). */
344	    public BigDecimal figure(Claim claim, String grade) {
345	        return dues.figure(claim, grade);
346	    }
347	
348	    /** The due a claim shows, with its late charge (see {@link Dues#due}). */
349	    public BigDecimal due(Claim claim, String grade) {
350	        return dues.due(claim, grade);
351	    }
352	
353	    private static BigDecimal money(BigDecimal amount) {
354	        return amount.setScale(2, RoundingMode.UNNECESSARY);
355	    }
356	
357	    private static String clean(String note) {
358	        return note == null ? "" : note.trim();
359	    }
