544	/** DRAFT when added; DRAFT → OPEN → SETTLED, and DRAFT or OPEN → VOID. */
545	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
546	
547	/** A move of a claim's status: open, settle or void. */
548	export type ClaimAction = 'open' | 'settle' | 'void';
549	
550	export interface ClaimView {
551	  id: number;
552	  personId: number;
553	  /** The amount with two decimals, e.g. "10.25". */
554	  amount: string;
555	  /** yyyy-mm-dd */
556	  date: string;
557	  note: string;
558	  status: ClaimStatus;
559	  /** The sheet's number given when the claim was opened; null while DRAFT, and kept once VOID. */
560	  number: number | null;
561	  /**
562	   * The due fixed when the claim was settled, with two decimals; null when it is not fixed (not
563	   * settled, or the grade had no rate then), so its due follows the current rate.
564	   */
565	  settledDue: string | null;
566	  /** The user who opened the claim; null until it is opened. The opener cannot settle it. */
567	  openedBy: string | null;
568	  /** Whether the claim is bound by its person's last statement to the figure it had then. */
569	  stated: boolean;
570	  /** The figure the statement bound the claim to, with two decimals; null when unbound, or when it was n/a. */
571	  statedDue: string | null;
572	  /** The number of the SETTLED claim this one corrects; null unless it is a correction. */
573	  corrects: number | null;
574	}
575	
576	/** Whether a claim is a correction: its amount is below 0.00. It has no floor and no late charge. */
577	export function isCorrection(claim: ClaimView): boolean {
578	  return claim.amount.startsWith('-') && cents(claim.amount) !== 0;
579	}
580	
581	/** Whether a claim counts toward what is claimed and due: only OPEN and SETTLED claims do. */
582	export function counts(claim: ClaimView): boolean {
583	  return claim.status === 'OPEN' || claim.status === 'SETTLED';
584	}
585	
586	/** A claim's due-by (yyyy-mm-dd): its date plus the sheet's terms in days. */
587	export function dueBy(claim: ClaimView, terms: number): string {
588	  const [y, m, d] = claim.date.split('-').map(Number);
589	  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
590	}
591	
592	/** Whether a claim is overdue: it is OPEN and its due-by is before the sheet's today. */
593	export function overdue(claim: ClaimView, terms: number, today: string): boolean {
594	  return claim.status === 'OPEN' && today !== '' && dueBy(claim, terms) < today;
595	}
596	
597	/** What a late charge is worked from: the sheet's late percent, terms and today. */
598	export interface LateTerms {
599	  /** The late percent with two decimals. */
600	  pct: string;
601	  terms: number;
602	  /** The sheet's today (yyyy-mm-dd); empty when none is loaded. */
603	  today: string;
604	}
605	
606	/**
607	 * Whether a claim's live figures round half up (else half to even): when the date it rounds by is
608	 * before the policy date, or the sheet's today when no policy date is set. A correction rounds by the
609	 * date of the claim it corrects, found by number among its person's claims (its own when not found).
610	 */
611	export function roundsHalfUp(claim: ClaimView, claims: ClaimView[], policyDate: string, today: string): boolean {
612	  const corrected = claim.corrects === null
613	    ? undefined
614	    : claims.find((c) => c.personId === claim.personId && c.number === claim.corrects);
615	  const date = corrected?.date ?? claim.date;
616	  const policy = policyDate || today;
617	  return policy !== '' && date < policy;
618	}
619	
620	/** How many full 30 days an overdue claim is past its due-by on the sheet's today; 0 when not overdue. */
621	export function latePeriods(claim: ClaimView, late: LateTerms): number {
622	  if (!overdue(claim, late.terms, late.today)) return 0;
623	  const days = (Date.parse(late.today) - Date.parse(dueBy(claim, late.terms))) / 86_400_000;
624	  return Math.floor(days / 30);
625	}
