629	  /** Empty means the sheet's today (or, on an edit, the claim's own date). */
630	  date: string | null;
631	  note: string;
632	  /** The number of the claim a correction corrects; null on any other claim. */
633	  corrects: number | null;
634	}
635	
636	/** An amount as a claim takes it: up to two decimals, below 0.00 only on a correction. */
637	export const AMOUNT = /^-?\d{1,12}(\.\d{1,2})?$/;
638	
639	/** A claim number as the form takes it. */
640	export const CLAIM_NUMBER = /^[1-9]\d{0,8}$/;
641	
642	/** A two-decimal amount in whole cents, so sums are exact. */
643	export function cents(amount: string): number {
644	  const negative = amount.startsWith('-');
645	  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
646	  const abs = Number(whole) * 100 + Number(frac.padEnd(2, '0'));
647	  return negative ? -abs : abs;
648	}
649	
650	/** Whole cents shown with two decimals. */
651	export function money(cents: number): string {
652	  const abs = Math.abs(cents);
653	  return `${cents < 0 ? '-' : ''}${Math.trunc(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
654	}
655	
656	// The claims people on a sheet make, read from and written to the store.
657	@Injectable({ providedIn: 'root' })
658	export class ClaimsApi {
659	  private readonly http = inject(HttpClient);
660	
661	  /** The sheet's claims, newest first. */
662	  list(sheet: string): Promise<ClaimView[]> {
663	    return firstValueFrom(this.http.get<ClaimView[]>(`${this.url(sheet)}/claims`));
664	  }
665	
666	  add(sheet: string, personId: number, form: ClaimForm): Promise<ClaimView> {
667	    return firstValueFrom(this.http.post<ClaimView>(`${this.url(sheet)}/people/${personId}/claims`, form));
668	  }
669	
670	  edit(sheet: string, id: number, form: ClaimForm): Promise<ClaimView> {
671	    return firstValueFrom(this.http.put<ClaimView>(`${this.url(sheet)}/claims/${id}`, form));
672	  }
673	
674	  /**
675	   * Move a claim's status; refused (409) when its status does not allow the move,
676	   * or when the user settling it is the one who opened it.
677	   */
678	  act(sheet: string, id: number, action: ClaimAction): Promise<ClaimView> {
679	    return firstValueFrom(this.http.post<ClaimView>(`${this.url(sheet)}/claims/${id}/${action}`, null));
680	  }
681	
682	  private url(sheet: string): string {
683	    return `/api/sheets/${encodeURIComponent(sheet)}`;
684	  }
685	}
686	import { HttpErrorResponse } from '@angular/common/http';
687	import { Component, inject, input, output, signal } from '@angular/core';
688	import { AMOUNT, CLAIM_NUMBER, ClaimAction, ClaimView, ClaimsApi, cents, dueBy, money, overdue, roundsHalfUp } from '../../core/claims';
689	import { GradeView, gradeOn } from '../../core/people';
690	import { PeriodView, periodOn } from '../../core/periods';
691	import { NO_RATE, RateView, claimDueCents } from '../../core/rates';
692	import { Session } from '../../core/session';
693	
694	// A person's claims: listed newest first, added and edited through one form on the person's row,
695	// and moved through their statuses (open, settle, void) from each claim's row.
696	const PAST: Record<ClaimAction, string> = { open: 'opened', settle: 'settled', void: 'voided' };
697	
698	@Component({
699	  selector: 'app-claims',
700	  template: `
701	    <form (submit)="save($event)" [attr.aria-label]="(editing() === null ? 'Add a claim for ' : 'Edit a claim of ') + personName()">
702	      <label [for]="'claim-form-amount-' + personId()">Amount</label>
703	      <input
704	        [id]="'claim-form-amount-' + personId()"
705	        data-testid="claim-form-amount"
706	        inputmode="decimal"
707	        [value]="amount()"
708	        (input)="amount.set(value($event)); error.set(null)"
709	      />
710	      <label [for]="'claim-form-date-' + personId()">Date</label>
711	      <input
712	        [id]="'claim-form-date-' + personId()"
713	        type="date"
714	        data-testid="claim-form-date"
715	        [value]="date()"
716	        (input)="date.set(value($event)); error.set(null)"
717	      />
718	      <label [for]="'claim-form-note-' + personId()">Note</label>
719	      <input
720	        [id]="'claim-form-note-' + personId()"
721	        data-testid="claim-form-note"
722	        [value]="note()"
723	        (input)="note.set(value($event)); error.set(null)"
724	      />
725	      <label [for]="'claim-form-corrects-' + personId()">Corrects claim no.</label>
726	      <input
727	        [id]="'claim-form-corrects-' + personId()"
728	        data-testid="claim-form-corrects"
729	        inputmode="numeric"
730	        [value]="corrects()"
731	        (input)="corrects.set(value($event)); error.set(null)"
732	      />
733	      <button type="submit" data-testid="claim-form-submit">
734	        {{ editing() === null ? 'Add claim' : 'Save claim' }}
735	      </button>
736	      @if (editing() !== null) {
737	        <button type="button" data-testid="claim-form-cancel" (click)="reset()">Cancel</button>
738	      }
739	      @if (error(); as message) {
740	        <p role="alert" data-testid="claim-form-error">{{ message }}</p>
741	      }
742	    </form>
743	    <ul [attr.aria-label]="'Claims of ' + personName()">
744	      @for (c of claims(); track c.id) {
745	        <li [attr.data-testid]="'claim-row-' + c.id">
746	          <span>No. <span data-testid="claim-number">{{ c.number ?? '' }}</span></span>
747	          <span data-testid="claim-amount">{{ c.amount }}</span>
748	          <span data-testid="claim-date">{{ c.date }}</span>
749	          <span data-testid="claim-note">{{ c.note }}</span>
750	          <span>Due <span data-testid="claim-due">{{ dueOf(c) }}</span></span>
751	          <span>Due by <span data-testid="claim-due-by">{{ dueByOf(c) }}</span></span>
752	          <span>Overdue <span data-testid="claim-overdue">{{ overdueOf(c) ? 'yes' : 'no' }}</span></span>
753	          <span>Period <span data-testid="claim-period">{{ periodOf(c) }}</span></span>
754	          <span data-testid="claim-status">{{ c.status }}</span>
755	          <span>Stated <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span></span>
756	          <span>Corrects <span data-testid="claim-corrects">{{ c.corrects ?? '' }}</span></span>
757	          <span>Opened by <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span></span>
758	          <button
759	            type="button"
760	            data-testid="claim-edit"
761	            [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date"
762	            (click)="open(c)"
763	          >
764	            Edit
765	          </button>
766	          @for (a of actions; track a.action) {
767	            <button
768	              type="button"
769	              [attr.data-testid]="'claim-' + a.action"
770	              [attr.aria-label]="a.label + ' claim of ' + c.amount + ' on ' + c.date"
771	              (click)="act(c, a.action)"
772	            >
773	              {{ a.label }}
774	            </button>
775	          }
776	          @if (claimError()?.id === c.id) {
777	            <p role="alert" data-testid="claim-error">{{ claimError()?.message }}</p>
778	          }
779	        </li>
780	      }
781	    </ul>
782	  `,
783	})
784	export class Claims {
785	  private readonly session = inject(Session);
786	  private readonly api = inject(ClaimsApi);
787	
788	  readonly personId = input.required<number>();
789	  readonly personName = input.required<string>();
790	  /** The person's claims, newest first. */
791	  readonly claims = input.required<ClaimView[]>();
792	  /** The person's grades by the date each is in force from; each claim uses the one on its date. */
793	  readonly grades = input.required<GradeView[]>();
794	  /** The sheet's rates; each claim uses the one its person's grade has in force on its date. */
795	  readonly rates = input.required<RateView[]>();
796	  /** The sheet's periods; each claim belongs to the one whose dates contain its date, or to none. */
797	  readonly periods = input.required<PeriodView[]>();
798	  /** A claim added or saved through the form. */
799	  readonly saved = output<ClaimView>();
800	
801	  protected readonly amount = signal('');
802	  protected readonly date = signal('');
803	  protected readonly note = signal('');
804	  /** The number of the SETTLED claim a correction corrects; empty on any other claim. */
805	  protected readonly corrects = signal('');
806	  /** The id of the claim open in the form, or null when the form adds a new claim. */
807	  protected readonly editing = signal<number | null>(null);
808	  protected readonly error = signal<string | null>(null);
809	  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
810	  private busy = false;
811	  /** The refusal of the last action taken on a claim's row, shown on that row. */
812	  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
813	  protected readonly actions: { action: ClaimAction; label: string }[] = [
814	    { action: 'open', label: 'Open' },
815	    { action: 'settle', label: 'Settle' },
816	    { action: 'void', label: 'Void' },
817	  ];
818	
819	  /**
820	   * What is due on a claim: the due fixed when it was settled, or else the figure its person's last
821	   * statement bound it to, or else its amount at the rate the
822	   * person's grade has in force on the claim's date (n/a when it is dated before every rate), with
823	   * its late charge on top while it is overdue.
824	   */
825	  protected dueOf(claim: ClaimView): string {
826	    const late = { pct: this.session.latePct(), terms: this.session.terms(), today: this.session.today() ?? '' };
827	    const halfUp = roundsHalfUp(claim, this.claims(), this.session.policyDate(), late.today);
828	    const figure = claimDueCents(claim, this.rates(), gradeOn(this.grades(), claim.date), cents(this.session.floor()), late, halfUp);
829	    return figure === null ? NO_RATE : money(figure);
830	  }
831	
832	  /** A claim's due-by: its date plus the sheet's terms. */
833	  protected dueByOf(claim: ClaimView): string {
834	    return dueBy(claim, this.session.terms());
835	  }
836	
837	  /** Whether a claim is OPEN and due by a date before the sheet's today. */
838	  protected overdueOf(claim: ClaimView): boolean {
839	    return overdue(claim, this.session.terms(), this.session.today() ?? '');
840	  }
841	
842	  /** The name of the period a claim's date falls in; empty when it falls in none. */
843	  protected periodOf(claim: ClaimView): string {
844	    return periodOn(this.periods(), claim.date)?.name ?? '';
845	  }
846	
847	  protected value(event: Event): string {
848	    return (event.target as HTMLInputElement).value;
849	  }
850	
851	  /**
852	   * Open a claim's editor: the form takes its values. Only a DRAFT claim can be edited; any other is
853	   * refused with an error on its row (to change an OPEN claim, void it and add a new one), as is one
854	   * dated in a closed period.
855	   */
856	  protected open(claim: ClaimView): void {
857	    this.claimError.set(null);
858	    if (claim.status !== 'DRAFT') {
859	      this.reset();
860	      this.claimError.set({
861	        id: claim.id,
862	        message: `A ${claim.status} claim cannot be edited; void it and add a new one.`,
863	      });
864	      return;
865	    }
866	    const period = periodOn(this.periods(), claim.date);
867	    if (period?.closed) {
868	      this.reset();
869	      this.claimError.set({ id: claim.id, message: `Period ${period.name} is closed, so its claims cannot be edited.` });
870	      return;
871	    }
872	    this.editing.set(claim.id);
873	    this.amount.set(claim.amount);
874	    this.date.set(claim.date);
875	    this.note.set(claim.note);
876	    this.corrects.set(claim.corrects === null ? '' : String(claim.corrects));
877	    this.error.set(null);
878	  }
879	
880	  /** Move a claim's status; a move its status does not allow is refused with an error on its row. */
881	  protected async act(claim: ClaimView, action: ClaimAction): Promise<void> {
882	    this.claimError.set(null);
883	    const sheet = this.session.sheet();
884	    if (!sheet) return;
885	    try {
886	      this.saved.emit(await this.api.act(sheet, claim.id, action));
887	    } catch (e) {
888	      const own = action === 'settle' && claim.status === 'OPEN' && claim.openedBy === this.session.user()?.trim();
889	      const overLimit = action === 'settle' && e instanceof HttpErrorResponse && e.status === 403;
890	      this.claimError.set({
891	        id: claim.id,
892	        message: own
893	          ? 'You opened this claim, so someone else must settle it.'
894	          : overLimit
895	            ? 'Its due is above the clerk limit, so a steward must settle it.'
896	            : `A ${claim.status} claim cannot be ${PAST[action]}.`,
897	      });
898	    }
899	  }
900	
901	  protected reset(): void {
902	    this.editing.set(null);
903	    this.amount.set('');
904	    this.date.set('');
905	    this.note.set('');
906	    this.corrects.set('');
907	    this.error.set(null);
908	  }
909	
910	  protected async save(event: Event): Promise<void> {
911	    event.preventDefault();
912	    if (this.busy) return;
913	    this.error.set(null);
914	    const sheet = this.session.sheet();
915	    if (!sheet) return;
916	    const amount = this.amount().trim();
917	    if (!AMOUNT.test(amount)) {
918	      this.error.set('Type an amount with up to two decimals; below 0.00 only for a correction.');
919	      return;
920	    }
921	    const corrects = this.corrects().trim();
922	    if (corrects !== '' && !CLAIM_NUMBER.test(corrects)) {
923	      this.error.set('Type the number of the claim it corrects.');
924	      return;
925	    }
926	    const form = { amount, date: this.date().trim() || null, note: this.note(), corrects: corrects === '' ? null : Number(corrects) };
927	    const id = this.editing();
928	    this.busy = true;
929	    try {
930	      const claim = id === null
931	        ? await this.api.add(sheet, this.personId(), form)
932	        : await this.api.edit(sheet, id, form);
933	      this.saved.emit(claim);
934	      this.reset();
935	    } catch {
936	      const verb = id === null ? 'added' : 'saved';
937	      this.error.set(amount.startsWith('-') || corrects !== ''
938	        ? `The claim could not be ${verb}: a correction (an amount below 0.00) must name a SETTLED claim of ${this.personName()}, and only a correction names one.`
939	        : `The claim could not be ${verb}.`);
940	    } finally {
941	      this.busy = false;
942	    }
943	  }
944	}
