354	        this.retireDates.clear();
355	        this.patronError.set(null);
356	        this.patronChoices.clear();
357	        if (sheet) void this.reload(sheet);
358	      });
359	    });
360	  }
361	
362	  protected claimsOf(personId: number): ClaimView[] {
363	    return this.byPerson().get(personId) ?? [];
364	  }
365	
366	  /** A person's claims that count in the live totals (see countsLive). */
367	  private countingOf(personId: number): ClaimView[] {
368	    const person = this.people().find((p) => p.id === personId);
369	    return person ? this.claimsOf(personId).filter((c) => countsLive(c, person)) : [];
370	  }
371	
372	  /** What a person has claimed: the sum of their OPEN and SETTLED claims' amounts (see countsLive). */
373	  protected claimed(personId: number): string {
374	    return money(this.claimedCents(personId));
375	  }
376	
377	  private claimedCents(personId: number): number {
378	    return this.countingOf(personId).reduce((sum, c) => sum + cents(c.amount), 0);
379	  }
380	
381	  /** A person's overdue claims that count in the live totals (see countsLive). */
382	  protected overdueOf(personId: number): ClaimView[] {
383	    return this.countingOf(personId).filter((c) => overdue(c, this.session.terms(), this.today()));
384	  }
385	
386	  /** The due of a person's counting overdue claims added up (a claim with no figure adds nothing). */
387	  protected overdueTotalOf(person: PersonView): string {
388	    return money(this.overdueCents(person));
389	  }
390	
391	  private overdueCents(person: PersonView): number {
392	    return this.overdueOf(person.id).reduce(
393	      (sum, c) => sum + (this.dueCents(c, person) ?? 0),
394	      0,
395	    );
396	  }
397	
398	  /** The grade a person has in force on the sheet's today. */
399	  protected gradeOf(person: PersonView): Grade {
400	    return gradeOn(person.grades, this.today());
401	  }
402	
403	  /** The rate a grade has in force on the sheet's today (a two-decimal percent), or null when it has none. */
404	  protected pctOf(grade: Grade): string | null {
405	    return rateOn(this.rates(), grade, this.today());
406	  }
407	
408	  /** A person's due-total: the sum of their counting claims' due figures, or n/a (see dueTotalCents). */
409	  protected dueTotalOf(person: PersonView): string {
410	    const total = this.dueTotalCents(person);
411	    return total === null ? NO_RATE : money(total);
412	  }
413	
414	  /**
415	   * A person's due-total in whole cents: the sum of the due figures of their OPEN and SETTLED claims
416	   * (0 with none; see countsLive). Null (n/a) when the grade they have in force on the sheet's today has no
417	   * rate, unless a claim has a figure (a fixed one, or one at the grade in force on its own date): then it
418	   * is the sum of the figures there are.
419	   */
420	  private dueTotalCents(person: PersonView): number | null {
421	    const dues = this.countingOf(person.id).map((c) => this.dueCents(c, person));
422	    if (this.pctOf(this.gradeOf(person)) === null && dues.every((d) => d === null)) return null;
423	    return dues.reduce<number>((sum, d) => sum + (d ?? 0), 0);
424	  }
425	
426	  /**
427	   * A claim's due in whole cents at the grade its person has in force on its date, with its late charge
428	   * (see claimDueCents).
429	   */
430	  private dueCents(claim: ClaimView, person: PersonView): number | null {
431	    const halfUp = roundsHalfUp(claim, this.claimsOf(person.id), this.session.policyDate(), this.today());
432	    return claimDueCents(claim, this.rates(), gradeOn(person.grades, claim.date), this.floorCents(), this.late(), halfUp);
433	  }
434	
435	  /** A person's patrons' names, sorted, comma and space separated. */
436	  protected patronsOf(person: PersonView): string {
437	    return this.patrons(person)
438	      .map((p) => p.name)
439	      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
440	      .join(', ');
441	  }
442	
443	  /** A person's backing: their patrons' due-totals added up, skipping those shown as n/a. */
444	  protected backingOf(person: PersonView): string {
445	    return money(this.patrons(person).reduce((sum, p) => sum + (this.dueTotalCents(p) ?? 0), 0));
446	  }
447	
448	  private patrons(person: PersonView): PersonView[] {
449	    return this.people().filter((p) => person.patronIds.includes(p.id));
450	  }
451	
452	  /** Name the person chosen on a person's row as their patron. */
453	  protected async addPatron(person: PersonView): Promise<void> {
454	    this.patronError.set(null);
455	    this.personError.set(null);
456	    const sheet = this.session.sheet();
457	    if (!sheet) return;
458	    const patronId = Number(this.patronChoices.get(person.id) ?? '');
459	    const refuse = (message: string) => this.patronError.set({ id: person.id, message });
460	    if (!patronId) {
461	      refuse('Choose a person to add as a patron.');
462	      return;
463	    }
464	    if (patronId === person.id) {
465	      refuse('A person cannot be their own patron.');
466	      return;
467	    }
468	    if (person.patronIds.includes(patronId)) {
469	      refuse('That person is already a patron.');
470	      return;
471	    }
472	    try {
473	      const saved = await this.api.addPatron(sheet, person.id, patronId);
474	      if (this.session.sheet() !== sheet) return;
475	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
476	    } catch {
477	      refuse('The patron could not be added.');
478	    }
479	  }
480	
481	  /** The last statement's due-total: n/a when it was, empty when none was taken. */
482	  protected statedTotalOf(person: PersonView): string {
483	    if (person.statementCount === 0) return '';
484	    return person.statementTotal ?? NO_RATE;
485	  }
486	
487	  /** Take a statement for a person: the row and their claims show what the store holds after it. */
488	  protected async statement(person: PersonView): Promise<void> {
489	    this.personError.set(null);
490	    const sheet = this.session.sheet();
491	    if (!sheet) return;
492	    try {
493	      const stated = await this.api.statement(sheet, person.id);
494	      if (this.session.sheet() !== sheet) return;
495	      this.people.update((list) => list.map((p) => (p.id === stated.person.id ? stated.person : p)));
496	      const byId = new Map(stated.claims.map((c) => [c.id, c]));
497	      this.claims.update((list) => list.map((c) => byId.get(c.id) ?? c));
498	    } catch {
499	      this.personError.set({ id: person.id, message: 'The statement could not be taken.' });
500	    }
501	  }
502	
503	  /** Retire a person from the date typed on their row, or from the sheet's today with none. */
504	  protected async retire(person: PersonView): Promise<void> {
505	    this.personError.set(null);
506	    const sheet = this.session.sheet();
507	    if (!sheet) return;
508	    const from = this.retireDates.get(person.id)?.trim() || null;
509	    try {
510	      const retired = await this.api.retire(sheet, person.id, from);
511	      if (this.session.sheet() !== sheet) return;
512	      this.people.update((list) => list.map((p) => (p.id === retired.id ? retired : p)));
513	    } catch {
514	      this.personError.set({ id: person.id, message: 'The person could not be retired.' });
515	    }
516	  }
517	
518	  /** Put a person on hold, or take them off it. */
519	  protected async toggleHold(person: PersonView): Promise<void> {
520	    this.personError.set(null);
521	    const sheet = this.session.sheet();
522	    if (!sheet) return;
523	    try {
524	      const saved = await this.api.hold(sheet, person.id, !person.held);
525	      if (this.session.sheet() !== sheet) return;
526	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
527	    } catch {
528	      this.personError.set({
529	        id: person.id,
530	        message: person.held ? 'The person could not be released.' : 'The person could not be put on hold.',
531	      });
532	    }
533	  }
534	
535	  /**
536	   * Download the people as a CSV file: a header line, then one line per person in list order, retired
537	   * people included, with the grade in force on the sheet's today, the retired-from date or nothing, and
538	   * the due-total as shown. Each line ends with a line feed.
539	   */
540	  protected exportCsv(): void {
541	    const lines = [
542	      ['name', 'grade', 'retired-from', 'due-total'],
543	      ...this.people().map((p) => [p.name, this.gradeOf(p), p.retiredFrom ?? '', this.dueTotalOf(p)]),
544	    ];
545	    const text = lines.map((fields) => fields.map(csvField).join(',') + '\n').join('');
546	    const url = URL.createObjectURL(new Blob([text], { type: 'text/csv;charset=utf-8' }));
547	    const link = document.createElement('a');
548	    link.href = url;
549	    link.download = `people-${this.session.sheet() ?? 'sheet'}.csv`;
550	    link.click();
551	    setTimeout(() => URL.revokeObjectURL(url));
552	  }
553	
554	  /** A rate set for a grade, in place of any it had from the same date. */
555	  protected rateSaved(rate: RateView): void {
556	    this.rates.update((list) => [...list.filter((r) => !sameSlot(r, rate)), rate]);
557	  }
558	
559	  /** A period added, kept in from-date order. */
560	  protected periodSaved(period: PeriodView): void {
561	    this.periods.update((list) => [...list, period].sort((a, b) => a.from.localeCompare(b.from)));
562	  }
563	
564	  /** A period closed or reopened, in its place. */
565	  protected periodChanged(period: PeriodView): void {
566	    this.periods.update((list) => list.map((p) => (p.id === period.id ? period : p)));
567	  }
568	
569	  /** A claim added (listed first, as the newest) or saved or moved (in its place). */
570	  protected claimSaved(claim: ClaimView): void {
571	    this.claims.update((list) =>
572	      list.some((c) => c.id === claim.id) ? list.map((c) => (c.id === claim.id ? claim : c)) : [claim, ...list],
573	    );
574	  }
575	
576	  /** A claim quick-added: its person listed when they were added for it, the claim first as the newest. */
577	  protected quickAdded(added: QuickAddView): void {
578	    if (added.personAdded) this.people.update((list) => [...list, added.person]);
579	    this.claimSaved(added.claim);
580	  }
581	
582	  protected value(event: Event): string {
583	    return (event.target as HTMLInputElement).value;
584	  }
585	
586	  protected checked(event: Event): boolean {
587	    return (event.target as HTMLInputElement).checked;
588	  }
589	
590	  protected gradeChosen(event: Event): Grade {
591	    return (event.target as HTMLSelectElement).value as Grade;
592	  }
593	
594	  /** Open a person's editor: the form takes their values. */
595	  protected open(person: PersonView): void {
596	    this.personError.set(null);
597	    this.editing.set(person.id);
598	    this.version.set(person.version);
599	    this.name.set(person.name);
600	    this.grade.set(this.gradeOf(person));
601	    this.gradeFrom.set(this.today());
602	    this.error.set(null);
603	  }
604	
605	  protected reset(): void {
606	    this.editing.set(null);
607	    this.name.set('');
608	    this.grade.set('A');
609	    this.gradeFrom.set(this.today());
610	    this.error.set(null);
611	  }
612	
613	  protected async save(event: Event): Promise<void> {
614	    event.preventDefault();
615	    if (this.busy) return;
616	    this.error.set(null);
617	    const sheet = this.session.sheet();
618	    if (!sheet) return;
619	    const form = { name: this.name(), grade: this.grade() };
620	    if (!form.name.trim()) {
621	      this.error.set('Type a name for the person.');
622	      return;
623	    }
624	    const id = this.editing();
625	    this.busy = true;
626	    try {
627	      if (id === null) {
628	        const added = await this.api.add(sheet, form);
629	        this.people.update((list) => [...list, added]);
630	      } else {
631	        const gradeFrom = this.gradeFrom().trim() || null;
632	        const saved = await this.api.edit(sheet, id, { ...form, gradeFrom, version: this.version() });
633	        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
634	      }
635	      this.reset();
636	    } catch (e) {
637	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
638	        await this.showCurrent(sheet, id);
639	        this.error.set('Someone else has saved this person since you opened it. The form shows their values now.');
640	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
641	        this.error.set('That name is already in use on this sheet.');
642	      } else {
643	        this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
644	      }
645	    } finally {
646	      this.busy = false;
647	    }
648	  }
649	
650	  /** Someone else saved the person open in the form: show what the store holds for them now. */
651	  private async showCurrent(sheet: string, id: number): Promise<void> {
652	    try {
653	      const current = (await this.api.list(sheet)).find((p) => p.id === id);
654	      if (!current || this.session.sheet() !== sheet || this.editing() !== id) return;
655	      this.people.update((list) => list.map((p) => (p.id === id ? current : p)));
656	      this.version.set(current.version);
657	      this.name.set(current.name);
658	      this.grade.set(this.gradeOf(current));
659	    } catch {
660	      // the form keeps what was typed; the refusal is still shown
661	    }
662	  }
663	
664	  private async reload(sheet: string): Promise<void> {
665	    const loads = this.session.loads();
666	    const [people, claims, rates, periods] = await Promise.all([
667	      this.api.list(sheet),
668	      this.claimsApi.list(sheet),
669	      this.ratesApi.list(sheet),
670	      this.periodsApi.list(sheet),
671	    ]);
672	    // A later load may have started while this one was in flight: only the latest is shown.
673	    if (this.session.sheet() === sheet && this.session.loads() === loads) {
674	      this.claims.set(claims);
675	      this.rates.set(rates);
676	      this.periods.set(periods);
677	      this.people.set(people);
678	    }
679	  }
680	}
